"const express = require('express');
const router = express.Router();
const humanController = require('./human.controller');
const { authenticateToken } = require('../../middleware/authMiddleware');

// Aplicar autenticación a todas las rutas
router.use(authenticateToken);

// Catálogos
router.get('/catalogos', humanController.getCatalogos);

// Pacientes
router.get('/patients', humanController.getPacientes);
router.post('/patients', humanController.createPaciente);
router.put('/patients/:id', humanController.updatePaciente);

// Laboratorios de Referencia
router.get('/reference-labs', humanController.getLaboratoriosReferencia);
router.post('/reference-labs', humanController.createLaboratorioReferencia);
router.put('/reference-labs/:id', humanController.updateLaboratorioReferencia);

// Exámenes y Resultados
router.get('/exams', humanController.getExamenes);
router.get('/exams/:id', humanController.getExamenById);
router.post('/exams', humanController.createExamen);
router.post('/exams/:id/results', humanController.saveResultados);

// Transmisión desde Analizadores
router.post('/analyzer/transmit', humanController.simularTransmision);

module.exports = router;
"

