"import api from '../../../services/api';

export const humanService = {
  // Catálogos
  getCatalogos: async () => {
    const response = await api.get('/human/catalogos');
    return response.data;
  },

  // Pacientes
  getPacientes: async () => {
    const response = await api.get('/human/patients');
    return response.data;
  },

  createPaciente: async (pacienteData) => {
    const response = await api.post('/human/patients', pacienteData);
    return response.data;
  },

  updatePaciente: async (id, pacienteData) => {
    const response = await api.put(`/human/patients/${id}`, pacienteData);
    return response.data;
  },

  // Laboratorios de Referencia
  getLaboratoriosReferencia: async () => {
    const response = await api.get('/human/reference-labs');
    return response.data;
  },

  createLaboratorioReferencia: async (labData) => {
    const response = await api.post('/human/reference-labs', labData);
    return response.data;
  },

  updateLaboratorioReferencia: async (id, labData) => {
    const response = await api.put(`/human/reference-labs/${id}`, labData);
    return response.data;
  },

  // Exámenes y resultados
  getExamenes: async (params = {}) => {
    const response = await api.get('/human/exams', { params });
    return response.data;
  },

  getExamenById: async (id) => {
    const response = await api.get(`/human/exams/${id}`);
    return response.data;
  },

  createExamen: async (examData) => {
    const response = await api.post('/human/exams', examData);
    return response.data;
  },

  saveResultados: async (id, resultadosData) => {
    const response = await api.post(`/human/exams/${id}/results`, { resultados: resultadosData });
    return response.data;
  },

  // Transmisión desde Analizadores
  transmitirAnalizador: async (transmissionData) => {
    const response = await api.post('/human/analyzer/transmit', transmissionData);
    return response.data;
  }
};
"

