  Check as CheckIcon,
  Print as PrintIcon
} from '@mui/icons-material';
import { useSnackbar } from 'notistack';
import { humanService } from '../api/humanService';

const themeColors = {
  primary: '#E07A5F', // Terracota suave
  primaryDark: '#C56248',
  secondary: '#F2CC8F', // Melocotón cálido
  background: '#FCFAF7', // Crema suave
  cardBg: '#FFFFFF',
  textMain: '#3D405B', // Gris cálido oscuro
  accentSage: '#81B29A', // Verde suave para activos
  errorSoft: '#FCECEB', // Rojo suave para fuera de rango
  errorText: '#C62828'
};

export default function TomaMuestras() {
  const [examenes, setExamenes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const { enqueueSnackbar } = useSnackbar();

  const fetchPendientesPorMuestra = async () => {
    setLoading(true);
    try {
      const res = await humanService.getExamenes();
      if (res.success) {
        // Filtrar y ordenar: solo POR_TOMAR_MUESTRA, y urgentes primero
        const pendientes = res.examenes.filter(ex => ex.estado === 'POR_TOMAR_MUESTRA');
        pendientes.sort((a, b) => {
          if (a.urgente && !b.urgente) return -1;
          if (!a.urgente && b.urgente) return 1;
          return new Date(a.fecha_creacion) - new Date(b.fecha_creacion);
        });
        setExamenes(pendientes);
      }
    } catch (err) {
      setError(err.message || 'Error de conexión');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPendientesPorMuestra();

    // Auto-refresh cada 30 segundos para ver nuevos ingresos
    const interval = setInterval(() => {
      fetchPendientesPorMuestra();
    }, 30000);
