"const net = require('net');

console.log("==================================================");
console.log("🚀 INICIANDO DEMO: CONTROLAB IA SNIFFER PROXY");
console.log("==================================================\n");

const LIS_PORT = 5000;
const SNIFFER_PORT = 5001;

// ---------------------------------------------------------
// 1. EL LIS (INFOLAB) SIMULADO
// Este servidor representa a Infolab recibiendo los resultados.
// ---------------------------------------------------------
const lisServer = net.createServer((socket) => {
    socket.on('data', (data) => {
        console.log(`\n[🏢 INFOLAB - PUERTO ${LIS_PORT}] Recibió una trama de datos del equipo.`);
        // Infolab normalmente responde con un ACK (Acknowledge)
        socket.write('ACK\r\n');
    });
});

lisServer.listen(LIS_PORT, () => {
    console.log(`[✔] LIS (Infolab) encendido y escuchando en el puerto ${LIS_PORT}`);
});

// ---------------------------------------------------------
// 2. EL SNIFFER DE CONTROLAB IA (EL SANTO GRIAL)
// Se pone en medio (Puerto 5001) para interceptar el tráfico.
