"const net = require('net');

const SNIFFER_PORT = 6001;
const TOTAL_TESTS = 100;

console.log(`[ANALIZADOR] Iniciando simulación de jornada laboral (100 pruebas)`);
console.log(`[ANALIZADOR] Conectando al puerto ${SNIFFER_PORT} (Nuestro Sniffer)`);

const socket = net.connect(SNIFFER_PORT, '127.0.0.1', () => {
    console.log(`[ANALIZADOR] Conectado con éxito.`);

    let counter = 0;

    const interval = setInterval(() => {
        counter++;

        let isQC = Math.random() < 0.15; // 15% de probabilidad de ser Control de Calidad
        let isRepeat = !isQC && Math.random() < 0.10; // 10% de repetición

        let patientId = isQC ? `QC-GLU-L${counter}` : (isRepeat ? `Paciente-REP` : `Paciente-${counter}`);

        const astmFrame = `H|\\^&|||Mindray|||||||P|1\r\nP|1|${patientId}|||Perez^Prueba\r\nO|1|Muestra${counter}|GLU^^^\r\nR|1|GLU^^^|105|mg/dL||N|||F`;

        socket.write(astmFrame);

        if (counter >= TOTAL_TESTS) {
            clearInterval(interval);
            console.log(`[ANALIZADOR] Jornada finalizada. 100 resultados enviados.`);
            setTimeout(() => {
                socket.end();
                process.exit(0);
            }, 1000);
        }
    }, 50); // Envía rápido (cada 50ms) para estresar la red
});

socket.on('data', (data) => {
    // Recibimos ACK silencioso
});

socket.on('error', (err) => {
    console.error(`[ANALIZADOR] Error de conexión: ${err.message}`);
    process.exit(1);
});"

"const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

// Webhook para recibir datos crudos del Sniffer .exe
exports.webhookSniffer = async (req, res) => {
    try {
        const { raw_frame, test_name, patient_id, is_qc, timestamp } = req.body;

        const newLog = await prisma.logSniffer.create({
            data: {
                test_name: test_name || 'UNKNOWN',
                patient_id: patient_id || 'UNKNOWN',
                is_qc: is_qc || false,
                raw_frame: raw_frame || '',
                fecha_registro: timestamp ? new Date(timestamp) : new Date(),
                procesado: false
            }
        });

        // NOTA FUTURA: Aquí llamaremos al servicio de inventario para descontar si es QC o repetición.
        // Por ahora, solo lo registramos para mostrarlo en el Dashboard.

        res.status(200).json({ success: true, message: 'Log registrado exitosamente en Controlab IA.', logId: newLog.id });
    } catch (error) {
        console.error('[Sniffer Webhook] Error:', error);
        res.status(500).json({ success: false, message: 'Error procesando la trama.' });
    }
};

// Obtener los logs para mostrarlos en el Dashboard Frontend
exports.getSnifferLogs = async (req, res) => {
    try {
        const logs = await prisma.logSniffer.findMany({
            orderBy: {
                fecha_registro: 'desc'
            },
            take: 100 // Solo traer los últimos 100 para el dashboard en vivo
        });

        res.status(200).json({ success: true, data: logs });
    } catch (error) {
        console.error('[Sniffer Get Logs] Error:', error);
        res.status(500).json({ success: false, message: 'Error obteniendo los logs.' });
    }
};"

