"const net = require('net');

const PORT = 5001;

console.log(`[LIS] Sistema de Gestión LIS arrancado. Escuchando resultados en el puerto ${PORT}`);

let resultCount = 0;

const server = net.createServer((socket) => {
    console.log(`[LIS] Conexión entrante desde equipo.`);

    socket.on('data', (data) => {
        // Simulamos que el LIS guarda el resultado
        resultCount++;
        console.log(`[LIS] Recibí resultado #${resultCount}. Guardando en BD para facturación.`);

        // Responder ACK al equipo
        socket.write(Buffer.from([0x06])); // ACK en protocolo ASTM/HL7
    });

    socket.on('error', (err) => {
        console.error(`[LIS] Error de conexión:`, err.message);
    });
});

server.listen(PORT, '127.0.0.1');"

